pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0 && depositAmount < type(uint120).max);
        vm.assume(collectAmount > 0 && collectAmount < type(uint120).max);

        // Initialization sequence
        c.SetMinSum(0);
        c.Initialized();

        // Setup: deposit by the actor
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Record total sum of balances and ETH balance before collect
        uint256 totalBalBefore = c.balances(actor);
        uint256 ethBalBefore = address(c).balance;

        // Attempt collect
        vm.prank(actor);
        bool collectOk = true;
        try c.Collect(collectAmount) {
            collectOk = true;
        } catch {
            collectOk = false;
        }

        // After collect, the invariant must hold: total balances == contract ETH balance
        if (collectOk) {
            uint256 totalBalAfter = c.balances(actor);
            uint256 ethBalAfter = address(c).balance;
            // The invariant: sum of all tracked balances equals contract's ETH balance
            // Since only one actor deposited, total balances == c.balances(actor)
            assertTrue(totalBalAfter == ethBalAfter);
        } else {
            // If collect reverted, balances and ETH should remain unchanged
            assertTrue(c.balances(actor) == totalBalBefore && address(c).balance == ethBalBefore);
        }
    }
}

