pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, uint256 depositAmt, uint256 collectAmt) public {
        // actor must be a valid callable address, not the contract itself, zero address, or precompile
        vm.assume(actor != address(0) && actor != address(c));
        // provide a moderate bound to avoid arithmetic overflow/underflow in the test logic itself
        depositAmt = bound(depositAmt, 1, 1000 ether);
        collectAmt = bound(collectAmt, 0, 1000 ether);

        // Ensure actor has enough ETH for the deposit
        vm.deal(actor, depositAmt);

        // Initialize the contract (required to enable Deposit)
        c.Initialized();

        // Perform the deposit
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // Ensure the actor's balance is at least MinSum for Collect to be allowed.
        // MinSum defaults to 1 ether, but we enforce to avoid revert due to MinSum check.
        vm.assume(depositAmt >= c.MinSum());
        // Also ensure collectAmt <= actor's recorded balance.
        vm.assume(collectAmt <= c.balances(actor));

        // Record balance before Collect
        uint256 balanceBefore = c.balances(actor);

        // Perform the Collect
        vm.prank(actor);
        c.Collect(collectAmt);

        // Record balance after Collect
        uint256 balanceAfter = c.balances(actor);

        // General invariant: Collect must not increase the caller's balance
        assertTrue(balanceAfter <= balanceBefore);
    }
}

