pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        depositAmount = bound(depositAmount, 1, type(uint256).max - 1);
        collectAmount = bound(collectAmount, 1, depositAmount);
        vm.assume(depositAmount >= collectAmount);

        // fund the contract with initial Ether to have a nonzero total ETH balance separate from token supply
        vm.deal(address(c), 10 ether);

        // record initial state
        uint256 initialTotalBalance = c.balances(actor) + c.balances(address(0)) + c.balances(address(this)) + c.balances(address(c));
        uint256 initialEth = address(c).balance;

        // actor deposits
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // actor collects
        vm.prank(actor);
        c.Collect(collectAmount);

        // final state
        uint256 finalTotalBalance = c.balances(actor) + c.balances(address(0)) + c.balances(address(this)) + c.balances(address(c));
        uint256 finalEth = address(c).balance;

        // the invariant: change in ETH balance equals change in total token balance
        // reference: deposit adds token, collect subtracts token -> deltaEth = deltaToken
        // mutant: deposit subtracts token, collect subtracts token -> deltaEth != deltaToken
        assertEq(finalEth - initialEth, finalTotalBalance - initialTotalBalance);
    }
}

