pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt) public {
        // Bound deposit amount to avoid overflow revert in the require check (balances + msg.value >= balances)
        depositAmt = bound(depositAmt, 1, type(uint256).max / 2);
        // Ensure collect amount is at most the deposit, so the collect can succeed if min sum is met
        collectAmt = bound(collectAmt, 1, depositAmt);

        // We need a fresh account to interact; use a deterministic address
        address actor = address(0x100);

        // Setup: initialize contract and set min sum to 0 to allow collects without holding 1 ether
        c.SetMinSum(0);
        c.Initialized();

        // Fund actor and deposit
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // Record balance before collect
        uint256 balanceBefore = c.balances(actor);

        // Perform collect
        vm.prank(actor);
        c.Collect(collectAmt);

        // Record balance after collect
        uint256 balanceAfter = c.balances(actor);

        // The invariant: after a successful collect (which should deduct the amount),
        // the balance must equal the previous balance minus the collected amount.
        // In the correct contract, balances are updated on deposit, so balanceBefore = depositAmt,
        // and balanceAfter = depositAmt - collectAmt.
        // In the buggy contract, balances are never updated, so balanceBefore = 0,
        // but collect still deducts from the stale 0 balance, causing underflow (revert) or unexpected behavior;
        // if it doesn't revert, balanceAfter would underflow to large number, breaking the invariant.
        // More generally: for any non-zero deposit, the balance before collect must be > 0 in correct version,
        // while it is 0 in buggy version, making balanceAfter != balanceBefore - collectAmt.
        assertTrue(balanceAfter == balanceBefore - collectAmt);
    }
}

