pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt) public {
        // Restrict to admissible domain: deposit > 0, collect > 0, and collect <= deposit
        vm.assume(depositAmt > 0 && collectAmt > 0 && collectAmt <= depositAmt);
        // Ensure deposit does not overflow
        vm.assume(depositAmt <= type(uint256).max - 1 ether);

        // Use a dedicated account
        address actor = address(0x1234);
        vm.deal(actor, depositAmt);

        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // Set MinSum low enough to allow collect
        c.SetMinSum(0);
        c.Initialized();

        vm.prank(actor);
        c.Collect(collectAmt);

        uint256 expectedBalance = depositAmt - collectAmt;
        uint256 actualBalance = c.balances(actor);
        // The reference correctly updates balances on deposit and on collect,
        // so expectedBalance equals actualBalance. The buggy version fails to
        // update balances on deposit, so actualBalance remains 0 (or wrong).
        assertTrue(actualBalance == expectedBalance);
    }
}

