contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 senderSeed) public {
        // Admissible domain: restrict amount to avoid overflow in require check and keep sender non-zero
        vm.assume(amount <= type(uint256).max / 2);
        address sender = address(uint160(senderSeed) + 1);
        vm.assume(sender != address(0));

        // Record initial total ether balance and total balances sum
        uint256 initBal = address(c).balance;
        uint256 initSum = c.balances(sender);

